export const AVA_NAMES = AVAS.map((a) => a[0]);

const byName = new Map(AVAS.map((a) => [a[0].toLowerCase(), a]));

/**
 * The AVA with exactly this name (any case): the AVA it sits in (Oakville: Napa Valley) and its
 * state (California; "" for an AVA across states).
 */
export function avaOf(name: string): { name: string; parent: string; state: string; states: string[] } | null {
  const a = byName.get(name.trim().toLowerCase());
  if (!a) return null;
  const states = a[2].split(",");
  return { name: a[0], parent: a[1], state: states.length === 1 ? (STATE_NAMES[states[0]!] ?? "") : "", states };
}
